UPDATE guia_proceso_paso p SET instrucciones=c.instrucciones
FROM guia_proceso g,contenido c WHERE p.guia_id=g.id AND g.slug=c.slug AND p.numero=c.numero;

UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-07',
 requisitos=requisitos || ' Seguimiento: cada paso comienza desde el menú correspondiente. En las ayudas selecciona una sugerencia, no sólo escribas el texto. Si no ves el módulo o su botón, solicita el permiso al administrador y vuelve a iniciar sesión; la guía no concede permisos. Si hay error al guardar, corrige el campo señalado y espera el mensaje de éxito antes de avanzar. Abrir módulo o Consultar siguiente paso no ejecuta la operación.'
WHERE slug IN ('transferencia-dos-hijos','beca-recargo-liquidacion','pagos-parciales-liquidacion','transferencia-vencida-500');

UPDATE guia_proceso_paso p SET precaucion=replace(precaucion,
 'Cargos vencidos, cancelados o liquidados no aparecen en esa captura.',
 'Cargos vencidos sólo aparecen si el plantel permite su transferencia o hay una autorización individual; cancelados, convenidos, liquidados y cargos con pago en revisión no se ofrecen.')
FROM guia_proceso g WHERE p.guia_id=g.id AND g.slug='transferencia-dos-hijos' AND p.numero=6;
UPDATE guia_proceso_paso p SET precaucion=replace(precaucion,
 'Si vence antes del último abono, el portal no lo ofrece y se debe registrar el saldo desde administración.',
 'Si vence antes del último abono, habilita su transferencia desde Adeudos de alumnos → Ver → Transferencia de cargo vencido, con motivo, o registra el saldo presencial desde administración; no cambies el vencimiento para hacerlo aparecer.')
FROM guia_proceso g WHERE p.guia_id=g.id AND g.slug='pagos-parciales-liquidacion' AND p.numero=1;
